import type * as vscode from 'vscode';

/**
 * Map panda engine events to Chat markdown progress.
 */
export class StreamMapper {
	private lastStatus = '';
	private streamedAssistant = false;

	constructor(private readonly stream: vscode.ChatResponseStream) { }

	handle(event: string, data: unknown): void {
		const d = (data && typeof data === 'object') ? data as Record<string, unknown> : {};

		switch (event) {
			case 'panda_stream': {
				const delta = typeof d.delta === 'string' ? d.delta
					: typeof d.text === 'string' ? d.text
						: typeof d.content === 'string' ? d.content
							: '';
				if (delta) {
					this.stream.markdown(delta);
					this.streamedAssistant = true;
				}
				break;
			}
			case 'panda_block': {
				const type = typeof d.type === 'string' ? d.type : '';
				const content = typeof d.content === 'string' ? d.content : '';
				if (!content) {
					break;
				}
				if (type === 'assistant_text') {
					if (!this.streamedAssistant) {
						this.stream.markdown(content);
						this.streamedAssistant = true;
					} else {
						// Prefer stream deltas; avoid duplicating full blocks when streaming already happened
						this.stream.markdown('\n\n' + content);
					}
				} else if (type === 'tool_call' || type === 'tool') {
					const name = typeof d.name === 'string' ? d.name : (typeof d.tool === 'string' ? d.tool : 'tool');
					this.stream.markdown(`\n\n- **Tool** \`${name}\`${content ? `: ${truncate(content, 240)}` : ''}\n`);
				} else if (type === 'system') {
					this.stream.markdown(`\n\n_${escapeMd(truncate(content, 300))}_\n`);
				}
				break;
			}
			case 'panda_status': {
				const msg = typeof d.message === 'string' ? d.message
					: typeof d.status === 'string' ? d.status
						: typeof d.text === 'string' ? d.text
							: '';
				if (msg && msg !== this.lastStatus) {
					this.lastStatus = msg;
					this.stream.markdown(`\n\n_${escapeMd(truncate(msg, 200))}_\n`);
				}
				break;
			}
			case 'panda_tool_start': {
				const name = typeof d.name === 'string' ? d.name : 'tool';
				this.stream.markdown(`\n\n- Running \`${name}\`…\n`);
				break;
			}
			case 'panda_tool_end': {
				const name = typeof d.name === 'string' ? d.name : 'tool';
				const ok = d.ok !== false;
				this.stream.markdown(`\n- \`${name}\` ${ok ? 'done' : 'failed'}\n`);
				break;
			}
			case 'panda_diag': {
				// Quiet: ignore verbose diag unless useful later
				break;
			}
			default:
				break;
		}
	}
}

function truncate(s: string, n: number): string {
	const t = s.replace(/\s+/g, ' ').trim();
	return t.length > n ? t.slice(0, n - 1) + '…' : t;
}

function escapeMd(s: string): string {
	return s.replace(/([\\`*_[\]{}()#+-.!])/g, '\\$1');
}

{
	"name": "aifront-agent",
	"displayName": "%displayName%",
	"description": "%description%",
	"version": "0.1.0",
	"publisher": "aifront",
	"license": "MIT",
	"engines": {
		"vscode": "^1.90.0"
	},
	"categories": [
		"AI",
		"Chat",
		"Other"
	],
	"activationEvents": [
		"onStartupFinished"
	],
	"main": "./out/extension",
	"enabledApiProposals": [
		"defaultChatParticipant",
		"chatParticipantAdditions",
		"chatProvider"
	],
	"scripts": {
		"compile": "gulp compile-extension:aifront-agent",
		"watch": "gulp watch-extension:aifront-agent"
	},
	"capabilities": {
		"virtualWorkspaces": false,
		"untrustedWorkspaces": {
			"supported": "limited",
			"description": "%workspaceTrust.description%"
		}
	},
	"contributes": {
		"languageModelChatProviders": [
			{
				"vendor": "deepseek",
				"displayName": "DeepSeek",
				"configuration": {
					"type": "object",
					"properties": {
						"apiKey": {
							"type": "string",
							"secret": true,
							"minLength": 1,
							"description": "DeepSeek API key from platform.deepseek.com",
							"title": "API Key"
						},
						"baseUrl": {
							"type": "string",
							"default": "https://api.deepseek.com",
							"description": "OpenAI-compatible API base URL (no trailing slash)",
							"title": "Base URL"
						}
					},
					"required": [
						"apiKey"
					]
				}
			}
		],
		"chatParticipants": [
			{
				"id": "aifront.agent",
				"fullName": "%chatParticipant.fullName%",
				"name": "aifront",
				"description": "%chatParticipant.description%",
				"isDefault": true,
				"modes": [
					"agent",
					"ask",
					"edit"
				],
				"disambiguation": [
					{
						"category": "coding_agent",
						"description": "Ask the AIFront coding agent to read, edit, or create files and run shell commands in the workspace.",
						"examples": [
							"Add a hello.txt file to the project",
							"Fix the TypeScript compile error in src/",
							"Refactor this function and update callers"
						]
					}
				]
			}
		],
		"configuration": {
			"title": "AIFront Agent",
			"properties": {
				"aifront.apiKey": {
					"type": "string",
					"default": "",
					"markdownDescription": "%config.apiKey%",
					"scope": "application",
					"order": 1
				},
				"aifront.baseUrl": {
					"type": "string",
					"default": "https://api.deepseek.com",
					"markdownDescription": "%config.baseUrl%",
					"scope": "application",
					"order": 2
				},
				"aifront.model": {
					"type": "string",
					"default": "deepseek-chat",
					"enum": [
						"deepseek-chat",
						"deepseek-reasoner",
						"deepseek-v4-flash",
						"deepseek-v4-pro"
					],
					"enumDescriptions": [
						"Official alias · general chat / coding",
						"Official alias · reasoner",
						"DeepSeek V4 Flash",
						"DeepSeek V4 Pro"
					],
					"markdownDescription": "%config.model%",
					"scope": "window",
					"order": 3
				},
				"aifront.enginePath": {
					"type": "string",
					"default": "",
					"markdownDescription": "%config.enginePath%",
					"scope": "window",
					"order": 10
				},
				"aifront.permissionMode": {
					"type": "string",
					"default": "bypassPermissions",
					"enum": [
						"bypassPermissions",
						"default",
						"acceptEdits",
						"plan"
					],
					"markdownDescription": "%config.permissionMode%",
					"scope": "window",
					"order": 11
				},
				"aifront.maxRounds": {
					"type": "number",
					"default": 40,
					"minimum": 1,
					"maximum": 80,
					"markdownDescription": "%config.maxRounds%",
					"scope": "window",
					"order": 12
				},
				"aifront.openChangedFiles": {
					"type": "boolean",
					"default": true,
					"markdownDescription": "%config.openChangedFiles%",
					"scope": "window",
					"order": 13
				}
			}
		},
		"commands": [
			{
				"command": "aifront.agent.setApiKey",
				"title": "%command.setApiKey%",
				"category": "AIFront"
			},
			{
				"command": "aifront.agent.selectModel",
				"title": "%command.selectModel%",
				"category": "AIFront"
			},
			{
				"command": "aifront.agent.showStatus",
				"title": "%command.showStatus%",
				"category": "AIFront"
			},
			{
				"command": "aifront.agent.openSettings",
				"title": "%command.openSettings%",
				"category": "AIFront"
			},
			{
				"command": "aifront.agent.manageModels",
				"title": "%command.manageModels%",
				"category": "AIFront"
			}
		]
	},
	"devDependencies": {
		"@types/node": "24.x"
	},
	"repository": {
		"type": "git",
		"url": "https://github.com/microsoft/vscode.git"
	}
}
